function HistoryChart({ snapshots, val, hidden }: { snapshots: Snapshot[]; val: (n: number) => string; hidden: boolean }) {
 if (snapshots.length < 2) return <div className="chart-empty"><span className="empty-chart-icon"><Layers3 size={28} /></span><h3>Your history starts here</h3><p>Save at least two snapshots to see your portfolio over time.<br />Values reflect your holdings at each snapshot, including additions and withdrawals.</p></div>;
 const all = snapshots.flatMap(s => [s.value, ...(s.invested === null ? [] : [s.invested])]);
 const low = Math.min(...all) * .96, high = Math.max(...all) * 1.04 || 1;
 const x = (i: number) => 12 + i / (snapshots.length - 1) * 718;
 const y = (n: number) => 222 - (n - low) / (high - low || 1) * 194;
 const path = snapshots.map((s, i) => `${i ? "L" : "M"}${x(i)},${y(s.value)}`).join(" ");
 const costPath = snapshots.map((s, i) => s.invested === null ? "" : `${i === 0 || snapshots[i - 1].invested === null ? "M" : "L"}${x(i)},${y(s.invested)}`).join(" ");
 return <div className="chart"><div className="chart-y">{[high, (high + low) / 2, low].map((n, i) => <span key={i}>{hidden ? "•••" : n >= 100000 ? `₹${(n / 100000).toFixed(1)}L` : n >= 1000 ? `₹${(n / 1000).toFixed(1)}k` : `₹${Math.round(n)}`}</span>)}</div><svg viewBox="0 0 742 250" role="img" aria-label="Portfolio value and invested amount across saved snapshots"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stopColor="var(--chart-1)" stopOpacity=".17"/><stop offset="1" stopColor="var(--chart-1)" stopOpacity="0"/></linearGradient></defs>{[28,125,222].map(n => <line key={n} x1="0" y1={n} x2="742" y2={n} stroke="var(--line)" strokeDasharray="3 5"/>)}<path d={`${path} L730,230 L12,230 Z`} fill="url(#area)"/><path d={costPath} fill="none" stroke="var(--chart-3)" strokeWidth="2" strokeDasharray="5 5"/><path d={path} fill="none" stroke="var(--chart-1)" strokeWidth="2.7" strokeLinejoin="round"/>{snapshots.map((s, i) => <circle key={i} cx={x(i)} cy={y(s.value)} r="4" className="chart-point"><title>{`${dateLabel(s.date)}: ${val(s.value)}`}</title></circle>)}</svg><div className="chart-x"><span>{dateLabel(snapshots[0].date)}</span><span>{dateLabel(snapshots[Math.floor(snapshots.length / 2)].date)}</span><span>{dateLabel(snapshots.at(-1)!.date)}</span></div></div>;
}
